const B1 = `linear-gradient(180deg,color-mix(in srgb,var(--acc) 72%,#fff),var(--acc) 55%,color-mix(in srgb,var(--acc) 84%,#000))`;
const B2 = `linear-gradient(180deg,color-mix(in srgb,var(--acc2) 72%,#fff),var(--acc2) 55%,color-mix(in srgb,var(--acc2) 84%,#000))`;

root.innerHTML = `
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:8;stroke-linecap:round;opacity:0.2">
    <path id="l0" d="M470 200 L470 350" />
    <path id="l1" d="M400 530 L245 750" />
    <path id="l2" d="M540 530 L695 750" />
  </svg>
  <div id="c0" style="${STY(B2, 440, 140)}left:250px;top:60px;font-size:42px;">AGILITY<br>ROBOTICS</div>
  <div id="c1" style="${STY(B1, 600, 180)}left:170px;top:350px;font-size:52px;">$465 MILLION<br>FUNDING BRIDGE</div>
  <div id="c2" style="${STY(B2, 410, 160)}left:40px;top:750px;font-size:40px;">SCALE<br>PRODUCTION</div>
  <div id="c3" style="${STY(B2, 410, 160)}left:490px;top:750px;font-size:40px;">COMMERCIAL<br>MATURITY</div>
`;

const cards = [0, 1, 2, 3].map(i => root.querySelector(`#c${i}`));
const lines = [0, 1, 2].map(i => {
  const el = root.querySelector(`#l${i}`);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});

function frame(t, p, d) {
  // 1. Center Hub ($465M) pops in first
  const s1 = spr(t, 0.2, 0.8, 5);
  cards[1].style.opacity = clamp(s1 * 2);
  cards[1].style.transform = `scale(${lerp(0.8, 1, s1)}) translateY(${lerp(20, 0, s1)}px)`;

  // 2. Agility Title (Top) slides in
  const s0 = spr(t, 0.5, 0.8, 5);
  cards[0].style.opacity = clamp(s0 * 2);
  cards[0].style.transform = `translateY(${lerp(-30, 0, s0)}px)`;

  // 3. Connection lines draw out
  const sl = spr(t, 1.2, 0.9, 4);
  lines.forEach(l => {
    l.el.style.strokeDashoffset = l.len * (1 - sl);
    l.el.style.opacity = clamp(sl * 2) * 0.3;
  });

  // 4. Satellite cards (Bottom) arrive
  const s2 = spr(t, 1.8, 0.8, 5);
  cards[2].style.opacity = clamp(s2 * 2);
  cards[2].style.transform = `translateX(${lerp(-40, 0, s2)}px)`;

  const s3 = spr(t, 2.1, 0.8, 5);
  cards[3].style.opacity = clamp(s3 * 2);
  cards[3].style.transform = `translateX(${lerp(40, 0, s3)}px)`;

  // Final hold at p=0.55
  if (p > 0.55) {
    cards.forEach(c => c.style.filter = 'none');
  }
}
